// 中学受験 国語（四字熟語・慣用句・ことわざ）単元の動く図解スライド（図のなかった単元に1つずつ）。
// 「なぜ？」の連鎖で7枚以上。上に図、下の帯にそのスライドのひとこと。
import type { DiagramElement, DiagramFigure } from './figures';
import type { Slide } from './diagram-kit';
import { show, bx, lb, ar, ln, ci, fresh, C, FILL } from './diagram-kit';

const hd = (t: string, color: string = C.ink) => lb(160, 13, t, 13, color, 'middle', true);
const cp = (t: string, color: string = C.main): DiagramElement => bx(10, 204, 300, 30, t, color, FILL.warm, 12);
const sl = (note: string, caption: string, ...els: DiagramElement[]): Slide => ({ note, add: fresh(...els, cp(caption)) });
const slc = (note: string, caption: string, color: string, ...els: DiagramElement[]): Slide => ({ note, add: fresh(...els, cp(caption, color)) });
const big = (t: string, y: number, c: string, f: string, h = 30, size = 13, x = 10, w = 300): DiagramElement => bx(x, y, w, h, t, c, f, size);
const cols = (labels: string[], y: number, h: number, c: string, f: string, size = 12, x0 = 10, x1 = 310, gap = 8): DiagramElement[] => {
  const n = labels.length;
  const w = (x1 - x0 - gap * (n - 1)) / n;
  return labels.map((t, i) => bx(x0 + i * (w + gap), y, w, h, t, c, f, size));
};
type RowOpt = { y0?: number; h?: number; gap?: number; lw?: number; c1?: string; f1?: string; c2?: string; f2?: string; s1?: number; s2?: number };
/** 左（語）→右（意味）の行を縦に並べる。 */
const rows = (items: [string, string][], opt?: RowOpt): DiagramElement[] => {
  const o = { y0: 26, h: 28, gap: 6, lw: 110, c1: C.blue, f1: FILL.blue, c2: C.green, f2: FILL.green, s1: 12, s2: 11, ...opt };
  const rx = 10 + o.lw + 26;
  return items.flatMap(([a, b], i) => {
    const y = o.y0 + i * (o.h + o.gap);
    return [bx(10, y, o.lw, o.h, a, o.c1, o.f1, o.s1), ar(10 + o.lw + 1, y + o.h / 2, rx - 1, y + o.h / 2, C.gray), bx(rx, y, 310 - rx, o.h, b, o.c2, o.f2, o.s2)];
  });
};
const rowsR = (items: [string, string][], opt?: RowOpt) => rows(items, { c1: C.red, f1: FILL.red, c2: C.red, f2: FILL.red, ...opt });
/** ことば → 絵（場面）→ 意味 の三つ組を、横一列に。 */
const trio = (a: string, b: string, c: string, y: number, h = 40, size = 12): DiagramElement[] => [
  bx(8, y, 88, h, a, C.blue, FILL.blue, size), ar(97, y + h / 2, 111, y + h / 2, C.gray),
  bx(112, y, 96, h, b, C.purple, FILL.purple, size - 1), ar(209, y + h / 2, 223, y + h / 2, C.gray),
  bx(224, y, 88, h, c, C.green, FILL.green, size),
];
const dn = (x: number, y1: number, y2: number, c: string = C.gray) => ar(x, y1, x, y2, c);

export const XF_CKC_FIGURES: Record<string, DiagramFigure> = {};
export const XF_CKC_SECTIONS: Record<string, string> = {};
const reg = (id: string, sec: number, fig: DiagramFigure) => {
  XF_CKC_FIGURES['xf_' + id] = fig;
  XF_CKC_SECTIONS[id + '#' + sec] = 'xf_' + id;
};

